/* eslint-disable max-len, max-params, max-depth */

'use strict';

// MODULES //

var loopOrder = require( '@stdlib/ndarray/base/nullary-loop-interchange-order' );
var blockSize = require( '@stdlib/ndarray/base/nullary-tiling-block-size' );
var takeIndexed = require( '@stdlib/array/base/take-indexed' );
var copyIndexed = require( '@stdlib/array/base/copy-indexed' );
var zeros = require( '@stdlib/array/base/zeros' );
var incrementOffsets = require( '@stdlib/ndarray/base/kernels/utils/increment-offsets' );
var setViewOffsets = require( '@stdlib/ndarray/base/set-descriptor-offsets' );
var offsets = require( '@stdlib/ndarray/base/offsets' );
var wrap = require( './callback_wrapper.js' );


// MAIN //

/**
* Applies a one-dimensional strided array function to an input ndarray according to a callback function via loop blocking.
*
* @private
* @param {Function} fcn - wrapper for a one-dimensional strided array function
* @param {Array<Object>} arrays - ndarray descriptors
* @param {ndarrayLike} ref - original input ndarray provided to a callback function
* @param {Array<Object>} views - initialized ndarray descriptors representing subarray views
* @param {Array<integer>} shape - loop dimensions
* @param {Array<integer>} stridesX - loop dimension strides for the input ndarray
* @param {Object} strategyX - strategy for marshaling data to and from an input ndarray view
* @param {NonNegativeIntegerArray} ibuf - workspace for storing iteration indices
* @param {NonNegativeIntegerArray} ldims - list of loop dimensions
* @param {NonNegativeIntegerArray} cdims - list of "core" dimensions
* @param {Options} opts - function options
* @param {boolean} hasOpts - boolean indicating whether to pass an options argument to a strided array function
* @param {Function} clbk - callback function
* @param {*} thisArg - callback execution context
* @returns {void}
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
* var zeros = require( '@stdlib/array/base/zeros' );
* var gfillBy = require( '@stdlib/blas/ext/base/ndarray/gfill-by' );
* var strategy = require( '@stdlib/ndarray/base/kernels/generic/unary-strided1d/strategy' );
*
* function clbk( value, idx ) {
*     return ( idx[ 4 ]*100 ) + ( idx[ 5 ]*10 ) + idx[ 6 ];
* }
*
* // Create a data buffer:
* var xbuf = new Float64Array( 12 );
*
* // Define the array shape:
* var xsh = [ 1, 1, 1, 1, 3, 2, 2 ];
*
* // Define the array strides:
* var sx = [ 12, 12, 12, 12, 4, 2, 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray descriptor:
* var x = {
*     'dtype': 'float64',
*     'data': xbuf,
*     'shape': xsh,
*     'strides': sx,
*     'offset': ox,
*     'order': 'row-major'
* };
*
* // Create an ndarray descriptor for the starting index (inclusive):
* var start = {
*     'dtype': 'float64',
*     'data': new Float64Array( [ 0.0 ] ),
*     'shape': [ 1, 1, 1, 1, 3 ],
*     'strides': [ 0, 0, 0, 0, 0 ],
*     'offset': 0,
*     'order': 'row-major'
* };
*
* // Create an ndarray descriptor for the ending index (exclusive):
* var end = {
*     'dtype': 'float64',
*     'data': new Float64Array( [ 4.0 ] ),
*     'shape': [ 1, 1, 1, 1, 3 ],
*     'strides': [ 0, 0, 0, 0, 0 ],
*     'offset': 0,
*     'order': 'row-major'
* };
*
* // Initialize ndarray descriptors representing subarray views:
* var views = [
*     {
*         'dtype': x.dtype,
*         'data': x.data,
*         'shape': [ 2, 2 ],
*         'strides': [ 2, 1 ],
*         'offset': x.offset,
*         'order': x.order
*     },
*     {
*         'dtype': start.dtype,
*         'data': start.data,
*         'shape': [],
*         'strides': [ 0 ],
*         'offset': start.offset,
*         'order': start.order
*     },
*     {
*         'dtype': end.dtype,
*         'data': end.data,
*         'shape': [],
*         'strides': [ 0 ],
*         'offset': end.offset,
*         'order': end.order
*     }
* ];
*
* // Resolve an input strategy when iterating over subarray views:
* var strategyX = strategy( views[ 0 ] );
*
* // Create a workspace array for storing iteration indices:
* var ibuf = zeros( xsh.length );
*
* // Define the loop and core dimensions:
* var ldims = [ 0, 1, 2, 3, 4 ];
* var cdims = [ 5, 6 ];
*
* // Apply strided function:
* kernel( gfillBy, [ x, start, end ], x, views, [ 1, 1, 1, 1, 3 ], [ 12, 12, 12, 12, 4 ], strategyX, ibuf, ldims, cdims, {}, false, clbk, {} );
*
* var arr = ndarray2array( x.data, x.shape, x.strides, x.offset, x.order );
* // returns [ [ [ [ [ [ [ 0.0, 1.0 ], [ 10.0, 11.0 ] ], [ [ 100.0, 101.0 ], [ 110.0, 111.0 ] ], [ [ 200.0, 201.0 ], [ 210.0, 211.0 ] ] ] ] ] ] ]
*/
function kernel( fcn, arrays, ref, views, shape, stridesX, strategyX, ibuf, ldims, cdims, opts, hasOpts, clbk, thisArg ) {
	var bsize;
	var dv0;
	var dv1;
	var dv2;
	var dv3;
	var dv4;
	var ov1;
	var ov2;
	var ov3;
	var ov4;
	var sh;
	var s0;
	var s1;
	var s2;
	var s3;
	var s4;
	var sv;
	var ov;
	var iv;
	var i0;
	var i1;
	var i2;
	var i3;
	var i4;
	var j0;
	var j1;
	var j2;
	var j3;
	var j4;
	var N;
	var x;
	var v;
	var o;
	var k;
	var f;

	// Note on variable naming convention: S#, dv#, i#, j# where # corresponds to the loop number, with `0` being the innermost loop...

	N = arrays.length;
	x = arrays[ 0 ];

	// Resolve the loop interchange order:
	o = loopOrder( shape, stridesX );
	sh = o.sh;
	sv = [ o.sx ];
	for ( k = 1; k < N; k++ ) {
		sv.push( takeIndexed( arrays[k].strides, o.idx ) );
	}
	// Determine the block size:
	bsize = blockSize( x.dtype );

	// Resolve a list of pointers to the first indexed elements in the respective ndarrays:
	ov = offsets( arrays );

	// Cache offset increments for the innermost loop...
	dv0 = [];
	for ( k = 0; k < N; k++ ) {
		dv0.push( sv[k][0] );
	}
	// Initialize loop variables...
	ov1 = zeros( N );
	ov2 = zeros( N );
	ov3 = zeros( N );
	ov4 = zeros( N );
	dv1 = zeros( N );
	dv2 = zeros( N );
	dv3 = zeros( N );
	dv4 = zeros( N );
	iv = zeros( N );

	// Shallow copy the list of views to an internal array so that we can update with reshaped views without impacting the original list of views:
	v = copyIndexed( views );

	// Iterate over blocks...
	for ( j4 = sh[4]; j4 > 0; ) {
		if ( j4 < bsize ) {
			s4 = j4;
			j4 = 0;
		} else {
			s4 = bsize;
			j4 -= bsize;
		}
		for ( k = 0; k < N; k++ ) {
			ov4[ k ] = ov[k] + ( j4*sv[k][4] );
		}
		for ( j3 = sh[3]; j3 > 0; ) {
			if ( j3 < bsize ) {
				s3 = j3;
				j3 = 0;
			} else {
				s3 = bsize;
				j3 -= bsize;
			}
			for ( k = 0; k < N; k++ ) {
				ov3[ k ] = ov4[k] + ( j3*sv[k][3] );
				dv4[ k ] = sv[k][4] - ( s3*sv[k][3] );
			}
			for ( j2 = sh[2]; j2 > 0; ) {
				if ( j2 < bsize ) {
					s2 = j2;
					j2 = 0;
				} else {
					s2 = bsize;
					j2 -= bsize;
				}
				for ( k = 0; k < N; k++ ) {
					ov2[ k ] = ov3[k] + ( j2*sv[k][2] );
					dv3[ k ] = sv[k][3] - ( s2*sv[k][2] );
				}
				for ( j1 = sh[1]; j1 > 0; ) {
					if ( j1 < bsize ) {
						s1 = j1;
						j1 = 0;
					} else {
						s1 = bsize;
						j1 -= bsize;
					}
					for ( k = 0; k < N; k++ ) {
						ov1[ k ] = ov2[k] + ( j1*sv[k][1] );
						dv2[ k ] = sv[k][2] - ( s1*sv[k][1] );
					}
					for ( j0 = sh[0]; j0 > 0; ) {
						if ( j0 < bsize ) {
							s0 = j0;
							j0 = 0;
						} else {
							s0 = bsize;
							j0 -= bsize;
						}
						// Compute index offsets and loop offset increments for the first ndarray elements in the current block...
						for ( k = 0; k < N; k++ ) {
							iv[ k ] = ov1[k] + ( j0*sv[k][0] );
							dv1[ k ] = sv[k][1] - ( s0*sv[k][0] );
						}
						// Iterate over the loop dimensions...
						for ( i4 = 0; i4 < s4; i4++ ) {
							for ( i3 = 0; i3 < s3; i3++ ) {
								for ( i2 = 0; i2 < s2; i2++ ) {
									for ( i1 = 0; i1 < s1; i1++ ) {
										for ( i0 = 0; i0 < s0; i0++ ) {
											setViewOffsets( views, iv );
											v[ 0 ] = strategyX.input( views[ 0 ] );
											f = wrap( ref, views[ 0 ], ibuf, ldims, [ j4+i4, j3+i3, j2+i2, j1+i1, j0+i0 ], cdims, clbk, thisArg );
											if ( hasOpts ) {
												fcn( v, opts, f );
											} else {
												fcn( v, f );
											}
											strategyX.output( views[ 0 ] );
											incrementOffsets( iv, dv0 );
										}
										incrementOffsets( iv, dv1 );
									}
									incrementOffsets( iv, dv2 );
								}
								incrementOffsets( iv, dv3 );
							}
							incrementOffsets( iv, dv4 );
						}
					}
				}
			}
		}
	}
}


// EXPORTS //

module.exports = kernel;
